lisher":"Poema Pocket","publish_date":null,"open_library_edition_id":"OL47163669M"}'::jsonb as exact union all select 'catalog_work_descriptions:13' as ref,(select to_jsonb(t) from public.catalog_work_descriptions t where t.work_id=987118003 and t.language='nl')='{"text":"Coco Barrington heeft afstand genomen van haar bekende Hollywoodfamilie en verdient haar geld als hondenuitlater. Wanneer ze op het huis van haar zus past, treft ze daar onverwacht acteur Leslie Baxter. Hun kennismaking zet haar vertrouwde leven in een ander licht. Tegelijk beginnen haar moeder en haar zus ieder aan een nieuwe fase in hun relatie. De roman volgt drie verschillende stellen die proberen liefde en familie een plaats te geven zonder alles vooraf te kunnen overzien.","work_id":987118003,"evidence":[{"note":"OneDayataTime2009, exact PoemaPocket paperback9789021012292. Front and exact KB title both Elke dag is er een; source suffix /druk4 is printing metadata and omitted from edition title, not a different Work. Source-person and KB authority share Q72653/ISNI. Original summary checked against primary publisher, no copied blurb.","type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p335988334"],"reference":"new-work-dossier-readings-019.json#114","checked_at":"2026-11-02T21:38:34.662Z"},{"type":"original_substantive_source_review","review":"content-review-009.json","sources":["https://www.penguinrandomhouse.com/books/172373/one-day-at-a-time-by-danielle-steel/","https://data.bibliotheken.nl/id/nbt/p335988334","https://openlibrary.org/works/OL14873505W"]},{"type":"explicit_contributor_roles","credits":[],"limitation":"Existing schema has one primary Work author; no synthetic combined-author identity or author merge."},{"type":"cover_front_review","sha256":"78f986df57c602a6cb4de03ffea082bfcf799690665938e7440f0c6cd668e0bb","cover_id":13574146,"reference":"cover-semantic-review-002.json","limitation":"Front title/author and source-edition binding; no bar